package com.ethk3.novaonepro.strategyv2;
import java.io.*;
/** Masked autoregression whose dependency is the used set. Exact subset-flow marginals. */
public final class FamilyF18KernelR26 implements TemporalModelR26 {
    private final double[][] bias=new double[10][10],context=new double[100][10],prefix=new double[10][10];private int[] previous;private long t;
    public void resetTemporalContext(){previous=null;}
    public int stateWidth(){return 2;}
    private double[] conditional(int mask){int p=Integer.bitCount(mask);double[] prob=new double[10];double max=-1e30,z=0;for(int n=0;n<10;n++)if((mask&(1<<n))==0){double s=bias[p][n]+(previous==null?0:context[p*10+n][previous[p]-1]);if(p>0)for(int used=0;used<10;used++)if((mask&(1<<used))!=0)s+=prefix[n][used]/p;prob[n]=s;max=Math.max(max,s);}for(int n=0;n<10;n++)if((mask&(1<<n))==0){prob[n]=Math.exp(prob[n]-max);z+=prob[n];}for(int n=0;n<10;n++)if((mask&(1<<n))==0)prob[n]/=z;return prob;}
    public void predict(float[][] p,float[] st){double[] mass=new double[1024];mass[0]=1;double[][] result=new double[10][10];for(int mask=0;mask<1023;mask++){if((mask&31)==0)ExecutionBudgetR26.poll();int position=Integer.bitCount(mask);double[] prob=conditional(mask);for(int n=0;n<10;n++)if((mask&(1<<n))==0){double flow=mass[mask]*prob[n];result[position][n]+=flow;mass[mask|1<<n]+=flow;}}for(int i=0;i<10;i++)for(int j=0;j<10;j++)p[i][j]=(float)result[i][j];st[0]=(float)Math.log1p(t);st[1]=(float)mass[1023];}
    public void update(int[] draw){OnlineModelsSU2.requireDraw(draw);double[][] gb=new double[10][10],gc=new double[100][10],gp=new double[10][10];int mask=0;for(int p=0;p<10;p++){double[] prob=conditional(mask);for(int n=0;n<10;n++)if((mask&(1<<n))==0){double g=prob[n]-(draw[p]==n+1?1:0);gb[p][n]=g;if(previous!=null)gc[p*10+n][previous[p]-1]=g;if(p>0)for(int used=0;used<10;used++)if((mask&(1<<used))!=0)gp[n][used]+=g/p;}mask|=1<<(draw[p]-1);}double[][][] params={bias,context,prefix},grad={gb,gc,gp};for(int k=0;k<params.length;k++)for(int i=0;i<params[k].length;i++)for(int j=0;j<params[k][i].length;j++)params[k][i][j]=Math.max(-8,Math.min(8,params[k][i][j]-.03*grad[k][i][j]));previous=draw.clone();t++;}
    public void write(DataOutput o)throws IOException{o.writeInt(0x26180001);o.writeLong(t);o.writeBoolean(previous!=null);if(previous!=null)for(int n:previous)o.writeInt(n);for(double[][] m:new double[][][]{bias,context,prefix})for(double[] row:m)for(double x:row)o.writeDouble(x);}
    public void read(DataInput in)throws IOException{if(in.readInt()!=0x26180001)throw new IOException("F18_ABI");t=in.readLong();if(t<0)throw new IOException("F18_CURSOR");previous=null;if(in.readBoolean()){previous=new int[10];for(int i=0;i<10;i++)previous[i]=in.readInt();OnlineModelsSU2.requireDraw(previous);}for(double[][] m:new double[][][]{bias,context,prefix})for(double[] row:m)for(int j=0;j<row.length;j++){row[j]=in.readDouble();if(!Double.isFinite(row[j])||Math.abs(row[j])>8)throw new IOException("F18_PARAMETER");}}
}
